using He_Thong_GYM.Models;using Microsoft.Data.SqlClient;using System.Data;
namespace He_Thong_GYM.DAL;
public sealed class SanPhamDAL
{
 public async Task<List<SanPham>> LayAsync(string? tuKhoa=null){var k=new List<SanPham>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("SELECT MaSP,MaSanPham,TenSP,DonGia,SoLuongTon,TrangThai,GiaNhap,TonToiThieu FROM dbo.SanPham WHERE @TuKhoa IS NULL OR MaSanPham LIKE '%' + @TuKhoa + '%' OR TenSP LIKE N'%' + @TuKhoa + N'%' ORDER BY MaSP DESC",c);m.Parameters.Add("@TuKhoa",SqlDbType.NVarChar,100).Value=string.IsNullOrWhiteSpace(tuKhoa)?DBNull.Value:tuKhoa.Trim();await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add(new SanPham{MaSP=r.GetInt32(0),MaSanPham=r.GetString(1),TenSP=r.GetString(2),DonGia=r.GetDecimal(3),SoLuongTon=r.GetInt32(4),TrangThai=r.GetString(5),GiaNhap=r.GetDecimal(6),TonToiThieu=r.GetInt32(7)});return k;}
 public async Task<int> BanAsync(int tv,int nv,int sp,int sl){await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("dbo.sp_BanSanPham",c){CommandType=CommandType.StoredProcedure};m.Parameters.AddWithValue("@MaTV",tv);m.Parameters.AddWithValue("@MaNV",nv);m.Parameters.AddWithValue("@MaSP",sp);m.Parameters.AddWithValue("@SoLuong",sl);var o=m.Parameters.Add("@MaHD",SqlDbType.Int);o.Direction=ParameterDirection.Output;await c.OpenAsync();await m.ExecuteNonQueryAsync();return(int)o.Value;}
 public async Task ThemAsync(SanPham sp){const string q="INSERT dbo.SanPham(TenSP,DonGia,SoLuongTon,TrangThai,GiaNhap,TonToiThieu,MaNCC) VALUES(@Ten,@Gia,@Ton,@TrangThai,@GiaNhap,@TonToiThieu,1);";await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);m.Parameters.AddWithValue("@Ten",sp.TenSP);m.Parameters.AddWithValue("@Gia",sp.DonGia);m.Parameters.AddWithValue("@Ton",sp.SoLuongTon);m.Parameters.AddWithValue("@TrangThai",string.IsNullOrWhiteSpace(sp.TrangThai)?"Còn bán":sp.TrangThai);m.Parameters.AddWithValue("@GiaNhap",sp.GiaNhap);m.Parameters.AddWithValue("@TonToiThieu",sp.TonToiThieu);await c.OpenAsync();await m.ExecuteNonQueryAsync();}
 public async Task CapNhatAsync(SanPham sp){const string q="UPDATE dbo.SanPham SET TenSP=@Ten,DonGia=@Gia,TrangThai=@TrangThai,GiaNhap=@GiaNhap,TonToiThieu=@TonToiThieu,NgayCapNhat=SYSDATETIME() WHERE MaSP=@MaSP;";await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);m.Parameters.AddWithValue("@Ten",sp.TenSP);m.Parameters.AddWithValue("@Gia",sp.DonGia);m.Parameters.AddWithValue("@TrangThai",sp.TrangThai);m.Parameters.AddWithValue("@GiaNhap",sp.GiaNhap);m.Parameters.AddWithValue("@TonToiThieu",sp.TonToiThieu);m.Parameters.AddWithValue("@MaSP",sp.MaSP);await c.OpenAsync();await m.ExecuteNonQueryAsync();}
 public async Task<int> NhapKhoAsync(int sp,int sl,decimal giaNhap,int nv,int ncc=1){await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("dbo.sp_NhapKho",c){CommandType=CommandType.StoredProcedure};m.Parameters.AddWithValue("@MaNCC",ncc);m.Parameters.AddWithValue("@MaNV",nv);m.Parameters.AddWithValue("@MaSP",sp);m.Parameters.AddWithValue("@SoLuong",sl);m.Parameters.AddWithValue("@DonGiaNhap",giaNhap);var o=m.Parameters.Add("@MaPNK",SqlDbType.Int);o.Direction=ParameterDirection.Output;await c.OpenAsync();await m.ExecuteNonQueryAsync();return(int)o.Value;}
}
